mapper.select:
SELECT *
FROM sample_notify
WHERE subbarcode = #{subbarcode}
  AND notify_type = #{notifyType}
  AND notify_date = #{notifyDate}
  AND del_flag = '0'
ORDER BY id DESC
LIMIT 1

SELECT n.id, n.notify_no, n.notify_type, n.notify_status, n.sign_status, n.notify_date, n.subbarcode, n.sample_name, n.study_no, n.project_no, n.participant_no, n.product, n.customer_name, n.sample_type, n.reason, n.delay_reason, n.expected_report_date, n.qc_stage, n.terminate_measure, n.remedy, n.remedy_other, n.reporter, n.report_time, n.reviewer, n.review_time, n.json_path, n.raw_docx_path, n.pdf_path, n.signed_pdf_path, COALESCE(NULLIF(n.signed_pdf_path, ''), NULLIF(n.pdf_path, ''), n.raw_docx_path) AS file_path, n.sign_contract_id, n.handler_by, hu.nick_name AS handler_name, n.handler_time, n.sender_by, su.nick_name AS sender_name, n.sender_time, n.send_to, n.send_cc, n.send_error, n.create_time, n.update_time FROM sample_notify n LEFT JOIN sys_user hu ON hu.user_id = n.handler_by LEFT JOIN sys_user su ON su.user_id = n.sender_by WHERE n.del_flag = '0' AND n.sign_status = 'signed' AND n.notify_status IN ('pending', 'sent', 'failed')
AND n.notify_type = #{q.notifyType}
AND n.notify_status = #{q.notifyStatus}
AND n.notify_date >= #{q.notifyDateStart}
AND n.notify_date <= #{q.notifyDateEnd}
AND n.subbarcode LIKE CONCAT('%', #{q.subbarcode}, '%')
AND n.project_no LIKE CONCAT('%', #{q.projectNo}, '%')
AND (n.subbarcode LIKE CONCAT('%', #{q.keyword}, '%') OR n.sample_name LIKE CONCAT('%', #{q.keyword}, '%') OR n.participant_no LIKE CONCAT('%', #{q.keyword}, '%'))
ORDER BY n.id DESC
